/* Whether one axis of the terminal has moved since the refusal, given
 * the terminal's size now and the two sizes recorded at the refusal --
 * curses' and the terminal's.
 *
 * The pin decides which of those two to compare against, and it is a
 * choice about where the numbers come from rather than about the axis.
 * Free, curses took its value from the ioctl, so either would do and
 * curses' is the one that survives an ioctl that had nothing to say.
 * Pinned, curses reports what was exported and the ioctl reports the
 * window, and pinning holds those apart for good: compared across, they
 * could never agree, so this answered "moved" every game and the caller
 * quoted a size that was not the player's window. Compared like for
 * like -- the terminal at the refusal against the terminal now -- the
 * mismatch cannot arise, and a player who drags the pinned axis is
 * answered rather than ignored. #169.
 *
 * Terminal against terminal needs the refusal to have had a terminal
 * size to record, and 0 is how refusedterm{lines,cols} say it did not.
 * Guarded the way blames() guards the same statics: an unknown size has
 * not been seen to move, where reading the 0 as a size would make every
 * axis differ from it and print the notice at every game to a player
 * who changed nothing. */
static int axis_moved(const char *name, int now, int refusedcurses,
		      int refusedterm) {
	if (!pinned(name)) return now != refusedcurses;
	return refusedterm != 0 && now != refusedterm;
}

/* Whether the terminal is a different size than when the panels were
 * last turned down for size, whether for the floor or for not fitting
 * the window.
 *
 * It answers one question, asked between games: has the player done
 * anything about the terminal? One who has -- grown it, and missed --
 * acted on what the notice told them and is owed an answer. One who has
 * not was told at startup, and telling them again every game is noise.
 * FALSE where the refusal was not about size at all (no terminal, or
 * one curses cannot drive): those do not change with a resize, and
 * refusedlines stays 0 to say so. */
int tui_size_changed_since_refusal(void) {
	struct winsize ws;

	if (refusedlines == 0) return FALSE;
	if (ioctl(fileno(stdout), TIOCGWINSZ, &ws) != 0) return FALSE;
	if (axis_moved("LINES", ws.ws_row, refusedlines, refusedtermlines))
		return TRUE;
	if (axis_moved("COLUMNS", ws.ws_col, refusedcols, refusedtermcols))
		return TRUE;
	return FALSE;
}

